package nl.smartstreamlabs.sbwdroneconfig;
import net.neoforged.bus.api.*;import net.neoforged.neoforge.event.level.*;import net.minecraft.server.level.*;
@net.neoforged.fml.common.EventBusSubscriber(modid=SbwDroneRangeConfig.MOD_ID)
public final class DefenseEvents{
 @SubscribeEvent public static void loaded(ChunkEvent.Load e){if(e.getLevel()instanceof ServerLevel l){long key=e.getChunk().getPos().toLong();l.getServer().tell(new net.minecraft.server.TickTask(l.getServer().getTickCount()+1,()->DefenseData.get(l).chunk(l,key)));}}
 @SubscribeEvent(priority=EventPriority.LOWEST)public static void crowbar(net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.RightClickBlock e){var s=e.getLevel().getBlockState(e.getPos());if(s.getBlock()instanceof DefenseBlock b&&e.getEntity().isShiftKeyDown()&&e.getItemStack().is(com.atsuishio.superbwarfare.init.ModTags.Items.TOOLS_CROWBAR)){e.setCanceled(true);e.setCancellationResult(e.getLevel().isClientSide?net.minecraft.world.InteractionResult.SUCCESS:b.interact(s,e.getLevel(),e.getPos(),e.getEntity(),e.getHand(),e.getHitVec()));}}
 @SubscribeEvent(priority=EventPriority.LOWEST)public static void linkEntity(net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.EntityInteract e){if(!(e.getItemStack().getItem()instanceof DefenseLinkTool)||!(e.getTarget()instanceof Mpl01Entity m))return;e.setCanceled(true);e.setCancellationResult(net.minecraft.world.InteractionResult.SUCCESS);if(e.getEntity()instanceof ServerPlayer p&&p.distanceToSqr(m)<36){m.claimOwner(p);var data=DefenseData.get(p.serverLevel());data.register(new DefenseData.Site(m.getUUID(),2,m.blockPosition(),net.minecraft.core.Direction.SOUTH,m.owner(),m.ownerName()));if(!DefenseData.allowed(p.serverLevel(),m.owner(),m.ownerName(),p)){DefenseLinkTool.reply(p,"DENIED");return;}if(p.isShiftKeyDown()){data.unlink(m.getUUID());DefenseLinkTool.reply(p,"UNLINKED");}else DefenseLinkTool.link(p,e.getItemStack(),m.getUUID());}}
 @SubscribeEvent(priority=EventPriority.HIGHEST)public static void breaking(BlockEvent.BreakEvent e){if(e.getState().getBlock()instanceof DefenseBlock&&e.getLevel()instanceof ServerLevel l){var b=DefenseBlock.main(l,e.getPos(),e.getState());if(b!=null&&!DefenseData.allowed(l,b.owner,b.ownerName,e.getPlayer()))e.setCanceled(true);}}
}
